    @Test void verifyModeIsReadOnlyAndApplyReplayCopiesExactObjectsOnce() throws Exception {
        var fake=new DatabaseDouble();var tool=new AiPictureImportTool(fake.db,fake.tx,verifier(),root.resolve("private"),publicProfile());var m=manifest(pack());var p=tool.verify(m);verifyNoInteractions(fake.db);assertFalse(Files.exists(root.resolve("private")));
        var first=tool.apply(m);assertEquals(p.rows().size(),first.inserted());assertEquals(0,first.replayed());int statements=fake.inserts;var again=tool.apply(m);assertEquals(0,again.inserted());assertEquals(p.rows().size(),again.replayed());assertEquals(statements,fake.inserts);for(var o:p.objects())assertArrayEquals(Files.readAllBytes(o.file()),Files.readAllBytes(root.resolve("private").resolve(o.objectKey())));
        assertEquals("committed",Json.map(Files.readString(first.recoveryFile())).get("state"));assertFalse(Json.bool(tool.checkRecovery(first.recoveryFile()).get("blocked"),true));verify(fake.db,never()).execute(contains("aip_dispatch"),anyMap());
    }
    @Test void changedOwnerMappingOrExistingTargetRejectsBeforeObjectsAndCannotOverwriteEdits() throws Exception {
        var pack=pack();var m=manifest(pack);var p=verifier().verify(m);var fake=new DatabaseDouble();var tool=new AiPictureImportTool(fake.db,fake.tx,verifier(),root.resolve("private"),publicProfile());fake.ownersExist=false;assertThrows(IllegalArgumentException.class,()->tool.apply(m));assertFalse(Files.exists(root.resolve("private")));fake.ownersExist=true;
        var original=target(p,"aip_asset");fake.rows.put(fake.identity(original.table(),original.keys()),Json.copy(original.values()));assertThrows(IllegalArgumentException.class,()->tool.apply(m));assertFalse(Files.exists(root.resolve("private")));fake.rows.clear();tool.apply(m);var session=target(p,"aip_session");fake.rows.get(fake.identity(session.table(),session.keys())).put("title","后来编辑");int writes=fake.inserts;assertThrows(IllegalArgumentException.class,()->tool.apply(m));assertEquals(writes,fake.inserts);assertEquals("后来编辑",fake.rows.get(fake.identity(session.table(),session.keys())).get("title"));
        var changed=Json.copy(pack);Json.map(Json.list(changed.get("owners")).get(0)).put("ruoyi_user_id",709);assertThrows(IllegalArgumentException.class,()->tool.apply(manifest(changed)));
    }
    @Test void immutableObjectCollisionStopsDatabaseAndInterruptedTransactionKeepsRecoveryLocator() throws Exception {
        var m=manifest(pack());var p=verifier().verify(m);var fake=new DatabaseDouble();Path privateRoot=root.resolve("private");var tool=new AiPictureImportTool(fake.db,fake.tx,verifier(),privateRoot,publicProfile());Path collision=privateRoot.resolve(p.objects().get(0).objectKey());Files.createDirectories(collision.getParent());Files.write(collision,new byte[]{4});assertThrows(IllegalArgumentException.class,()->tool.apply(m));assertEquals(0,fake.inserts);assertArrayEquals(new byte[]{4},Files.readAllBytes(collision));
        Files.write(collision,Files.readAllBytes(p.objects().get(0).file()));fake.failInsert=true;assertThrows(IllegalStateException.class,()->tool.apply(m));assertEquals(1,fake.rollbacks);assertTrue(fake.rows.isEmpty());assertTrue(fake.maps.isEmpty());Path journal=root.resolve("recovery-"+m.batchId()+".json");assertEquals("interrupted_check_database_before_recovery",Json.map(Files.readString(journal)).get("state"));assertTrue(Files.exists(collision));fake.failInsert=false;assertEquals(p.rows().size(),tool.apply(m).inserted());
    }
    @Test void recoveryIsReadOnlyAndBlocksLaterEditsNewReferencesMissingMappingsAndTamperedJournal() throws Exception {
        var m=manifest(pack());var p=verifier().verify(m);var fake=new DatabaseDouble();var tool=new AiPictureImportTool(fake.db,fake.tx,verifier(),root.resolve("private"),publicProfile());var applied=tool.apply(m);int writes=fake.inserts;var s=target(p,"aip_session");fake.rows.get(fake.identity(s.table(),s.keys())).put("row_version",3);assertTrue(Json.bool(tool.checkRecovery(applied.recoveryFile()).get("blocked"),false));fake.rows.get(fake.identity(s.table(),s.keys())).put("row_version",0);fake.newReference=Json.id();assertFalse(Json.list(tool.checkRecovery(applied.recoveryFile()).get("new_references")).isEmpty());fake.newReference=null;fake.maps.remove(fake.mapKey(m.dataset(),"asset",target(p,"aip_asset").sourceId()));assertTrue(Json.bool(tool.checkRecovery(applied.recoveryFile()).get("blocked"),false));assertEquals(writes,fake.inserts);
        var tampered=Json.map(Files.readString(applied.recoveryFile()));Json.map(Json.list(tampered.get("rows")).get(0)).put("created_by_batch",false);Files.writeString(applied.recoveryFile(),Json.write(tampered));assertThrows(IllegalArgumentException.class,()->tool.checkRecovery(applied.recoveryFile()));assertThrows(IllegalArgumentException.class,()->tool.apply(m));assertEquals(writes,fake.inserts);
    }

    private void directoryLink(Path link,Path target) throws Exception {
        assertTrue(link.normalize().startsWith(root));assertTrue(target.toRealPath().startsWith(root));
        if(!System.getProperty("os.name").startsWith("Windows")){Files.createSymbolicLink(link,target);return;}
        // Windows junction不需要额外symlink权限，两个目标都在本用例的TempDir内。
        String script="$ErrorActionPreference='Stop'; New-Item -ItemType Junction -Path '"+link.toString().replace("'","''")+"' -Target '"+target.toString().replace("'","''")+"' | Out-Null";
        var process=new ProcessBuilder("powershell.exe","-NoProfile","-NonInteractive","-EncodedCommand",Base64.getEncoder().encodeToString(script.getBytes(java.nio.charset.StandardCharsets.UTF_16LE))).redirectErrorStream(true).start();boolean done=process.waitFor(30,java.util.concurrent.TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertTrue(done,"人工目录junction创建超时");assertEquals(0,process.exitValue(),"人工目录junction创建失败");assertEquals(target.toRealPath(),link.toRealPath());
    }
    /** 模拟事务回滚及行重读；只证明工具的调用顺序，不代替真实MySQL事务证明。 */
    private static final class DatabaseDouble {
        final AiPictureRepository db=mock(AiPictureRepository.class);final TransactionTemplate tx;
        Map<String,Map<String,Object>> rows=new LinkedHashMap<>(),maps=new LinkedHashMap<>();boolean ownersExist=true,failInsert;String newReference;int inserts,rollbacks;
        String identity(String table,Map<String,?> keys){return table+":"+Json.write(Json.canonical(keys));}
        String mapKey(Object dataset,Object entity,Object source){return dataset+"/"+entity+"/"+source;}
        DatabaseDouble() {
            when(db.count(anyString(),anyMap())).thenAnswer(i->ownersExist?1L:0L);
            when(db.one(anyString(),anyMap())).thenAnswer(i->{String sql=i.getArgument(0);Map<String,Object> args=i.getArgument(1);if(sql.contains("FROM aip_import_map"))return maps.get(mapKey(args.get("dataset"),args.get("entity"),args.get("source")));String table=sql.split(" ")[3];return rows.get(identity(table,args));});
            when(db.query(anyString(),anyMap())).thenAnswer(i->{String sql=i.getArgument(0);return newReference!=null&&sql.contains(" FROM aip_session WHERE ")?List.of(Json.of("id",newReference)):List.of();});
            when(db.execute(anyString(),anyMap())).thenAnswer(i->{if(failInsert)throw new IllegalStateException("人工事务故障");String sql=i.getArgument(0);Map<String,Object> args=i.getArgument(1);inserts++;if(sql.startsWith("INSERT INTO aip_import_map")){maps.put(mapKey(args.get("dataset"),args.get("entity"),args.get("source")),Json.of("target_id",args.get("target"),"user_id",args.get("owner"),"sha256",args.get("hash"),"status","imported"));return 1;}
                String table=sql.substring("INSERT INTO ".length(),sql.indexOf('('));String[] columns=sql.substring(sql.indexOf('(')+1,sql.indexOf(')')).split(",");var values=new LinkedHashMap<String,Object>();for(int n=0;n<columns.length;n++){Object value=args.get("value"+n);if(value instanceof String text&&(text.startsWith("{")||text.startsWith("[")))value=JSON.parse(text);values.put(columns[n],value);}var keys=Json.of("id",values.get("id"));if(table.equals("aip_session_asset"))keys=Json.of("session_id",values.get("session_id"),"asset_id",values.get("asset_id"));if(table.equals("aip_plan_step"))keys=Json.of("turn_id",values.get("turn_id"),"step_id",values.get("step_id"));rows.put(identity(table,keys),values);return 1;});
            tx=new TransactionTemplate(new PlatformTransactionManager(){Map<String,Map<String,Object>> rowBefore,mapBefore;public TransactionStatus getTransaction(TransactionDefinition d){rowBefore=copy(rows);mapBefore=copy(maps);return new SimpleTransactionStatus();}public void commit(TransactionStatus s){}public void rollback(TransactionStatus s){rollbacks++;rows=rowBefore;maps=mapBefore;}});
        }
        static Map<String,Map<String,Object>> copy(Map<String,Map<String,Object>> source){var result=new LinkedHashMap<String,Map<String,Object>>();source.forEach((k,v)->result.put(k,Json.copy(v)));return result;}
    }
